<?php
require_once __DIR__ . '/public-common.php';

    $isGuest = !isset($_SESSION['user_id']) && ($_GET['guest'] ?? '') === '1';
    if (!$isGuest && !isset($_SESSION['user_id'])) {
        header('Location: index.php');
        exit();
    }
    if (!$isGuest && ($_SESSION['role'] ?? 'user') === 'admin') {
        header('Location: dashboard.php');
        exit();
    }
    
    $displayName = publicText($isGuest ? 'Guest visitor' : ($_SESSION['username'] ?? 'Resident'));
    $updates = publicRows('SELECT title, body, published_at FROM public_updates WHERE is_published = 1 ORDER BY published_at DESC LIMIT 6');
