    <div class="modal" id="login-modal" hidden><div class="modal-card"><button class="modal-close" type="button" aria-label="Close" onclick="closeLogin()">&times;</button><h2>Login to continue</h2><p>Sign in or create an account to use this dashboard action.</p><div class="modal-message" id="modal-message"></div><form id="modal-login"><label for="modal-username">Username</label><input id="modal-username" name="username" required autocomplete="username"><label for="modal-password">Password</label><input id="modal-password" name="password" type="password" required autocomplete="current-password"><button class="button" style="margin-top:18px;width:100%;justify-content:center" type="submit">Login</button></form><a href="auth.php" style="display:block;text-align:center;color:var(--teal);font-size:13px;margin-top:16px">Create an account</a></div></div>
    <script>
        const isGuest = <?= $isGuest ? 'true' : 'false' ?>;
        let pendingAction = null;
        function toggleMenu(button) { const header = document.getElementById('site-header'); const open = header.classList.toggle('open'); button.setAttribute('aria-expanded', open); }
        function openLogin(action) { pendingAction = action; document.getElementById('login-modal').hidden = false; document.getElementById('modal-username').focus(); }
        function closeLogin() { document.getElementById('login-modal').hidden = true; }
        function saveItem(button) { const key = 'brgy-saved-' + button.dataset.item; const saved = localStorage.getItem(key) === '1'; localStorage.setItem(key, saved ? '0' : '1'); button.classList.toggle('saved', !saved); button.innerHTML = saved ? '<i class="fa-regular fa-bookmark"></i> Save' : '<i class="fa-solid fa-bookmark"></i> Saved'; }
        document.querySelectorAll('[data-gated]').forEach(element => element.addEventListener('click', event => { if (isGuest) { event.preventDefault(); openLogin(element.dataset.gated); return; } if (element.dataset.gated === 'save') saveItem(element); if (element.dataset.gated === 'subscribe') window.location.href = 'services-programs#alerts'; if (element.dataset.gated === 'share') shareItem(element.dataset.share); }));
        function shareItem(item) { if (navigator.share) navigator.share({ title:item, url:location.origin + '/' + item }); else if (navigator.clipboard) navigator.clipboard.writeText(location.href).then(() => alert('Page link copied.')); else alert('Copy this page link to share it.'); }
        document.querySelectorAll('[data-share]').forEach(element => element.addEventListener('click', () => { if (element.dataset.share === 'official-documents') { window.location.href = 'official-documents'; return; } if (navigator.share) navigator.share({ title: element.dataset.share, url: location.origin + '/' + element.dataset.share }); else if (navigator.clipboard) navigator.clipboard.writeText(location.href).then(() => alert('Page link copied.')); else alert('Copy this page link to share it.'); }));
        document.getElementById('modal-login').addEventListener('submit', async event => { event.preventDefault(); const message = document.getElementById('modal-message'); try { const response = await fetch('bootstrap/login.php', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); const data = await response.json(); if (data.status === 'success') { window.location.href = 'user-dashboard.php' + (pendingAction ? '?action=' + encodeURIComponent(pendingAction) : ''); return; } message.textContent = data.message || 'Invalid username or password.'; } catch (error) { message.textContent = 'The service is temporarily unavailable.'; } message.style.display = 'block'; });
    </script>
